def checkFatturaUnivoca(annoRif, meseRif, tipoFattura, jdbcUrl, conn_Prop):

    query = f"""(
    SELECT FkIdEnte 
        ,Count(*) as nFatture
    FROM pfd.FattureTestata 
    where 
    AnnoRiferimento = {annoRif} and MeseRiferimento = {meseRif} 
    and FkTipologiaFattura = '{tipoFattura}'
    GROUP BY FkIdEnte
    ) as tb"""

    dfFattura = spark.read.jdbc(url=jdbcUrl, table=query, properties=conn_Prop) 

    return dfFattura.filter("nFatture > 1")

def checkCodiceMateriale(annoRif, meseRif, tipoFattura, jdbcUrl, conn_Prop):

    pac = {
    'anticipo': [
        'ANTICIPO ND 30%', 'ANTICIPO NA 30%', 'ANT ND ST 30%', 'ANT NA ST 30%'
        ],
    'acconto': [
        'ACCONTO NOT.DIG.', 'ACCONTO NOT.ANL.', 'STORNO 50% ANT.ND', 'STORNO 50% ANT.NA'
        ],
    'primo saldo': [
        'P SALDO PAC N.DIG.', 'P SALDO PAC N.ANL', 'STORNO 50% ANT.ND', 'STORNO 50% ANT.NA', 'STORNO ACCONTO ND', 'STORNO ACCONTO NA'
    ]
    }

    pal = {
        'anticipo': [
            'ANTICIPO ND 50%','ANTICIPO NA 50%', 'ANT ND ST 50%', 'ANT NA ST 50%'
            ],
        'primo saldo': [
            'P SALDO PAC N.DIG.', 'P SALDO PAC N.ANL', 'STORNO ANTICIPO ND', 'STORNO ANTICIPO NA'
        ]
    }

    codici_PAC = ', '.join({f'\'{codice}\'' for codice in pac.get(tipoFattura)})

    codici_PAL = ', '.join({f'\'{codice}\'' for codice in pal.get(tipoFattura, ['NONE'])})

    print(codici_PAC,"\n", codici_PAL)

    query = f"""(
        SELECT FT.IdFattura, FT.AnnoRiferimento, FT.MeseRiferimento, FT.FkIdEnte, FR.CodiceMateriale,
        CASE WHEN TC.Descrizione = 'PAC' AND 
            CodiceMateriale IN ({codici_PAC})
            THEN 'OK PAC'
            WHEN TC.Descrizione = 'PAL' AND 
            CodiceMateriale IN ({codici_PAL})
            THEN 'OK PAL'
        ELSE 'KO' END AS CheckCodiceContratto
        FROM pfd.FattureTestata FT
        INNER JOIN pfd.FattureRighe FR ON  IdFattura = FkIdFattura
        INNER JOIN pfd.Contratti C on FT.FkIdEnte = C.internalistitutionid
        INNER JOIN pfw.TipoContratto TC on C.FkIdTipoContratto = TC.IdTipoContratto
        WHERE FT.AnnoRiferimento = {annoRif} and FT.MeseRiferimento = {meseRif} AND FkTipologiaFattura = '{tipoFattura}'
    ) as tb"""

    dfFatture = spark.read.jdbc(url=jdbcUrl, table=query, properties=conn_Prop) 

    return dfFatture#.filter("CheckCodiceContratto = 'KO'")
